// coding-misk · Example 1 · First beat
// song composed with sections and tracks: each track plays its clips, switched on by the section lane (1 plays, 0 is silent, values in between fade)
// each .analyze("…") lights up its instrument in the Stage visual
setcpm(124/4)

const SECTIONS = [['Crescendo', 12], ['Loop', 8]]
const TEMPO = {'Crescendo': 124, 'Loop': 124}

// section lanes: 1 plays, 0 is silent, values in between fade
const section1 = "<1!12 0!8>"  // Crescendo · 12 bars · 124 BPM · A · Am
const section2 = "<0!12 1!8>"  // Loop · 8 bars · 124 BPM · A · Am

// ========== drums ==========
// Crescendo · bars 1-12 · pattern A~2
// Drums · RolandTR909
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR909").gain(0.48).mask(section1).velocity(section1).orbit(1).analyze("kick")
// Loop · bars 13-20 · pattern A~2
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR909").gain(0.48).mask(section2).velocity(section2).orbit(1).analyze("kick")

